// Lê direto de $json.choices[0].message.content.insights
const content = $json?.choices?.[0]?.message?.content;
let insights = [];

// Se vier objeto com .insights (caso use response_format json_object)
if (content && typeof content === 'object' && Array.isArray(content.insights)) {
  insights = content.insights;
} else if (typeof content === 'string') {
  // Se vier string JSON, tenta parsear e pegar .insights
  try {
    const parsed = JSON.parse(content);
    if (Array.isArray(parsed?.insights)) insights = parsed.insights;
  } catch (e) {
    insights = [];
  }
}

if (!Array.isArray(insights) || !insights.length) {
  throw new Error('Sem insights em $json.choices[0].message.content.insights');
}

// 1 item por insight
return insights.map((text, i) => ({ json: { index: i + 1, text } }));
